sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-35: FLEET - Complete Reservation
    var vehicleId = current.getValue('assigned_vehicle');
    var v = new GlideRecord('x_1850693_enterp_0_vehicle');
    if (vehicleId && v.get(vehicleId) && !current.check_in_odometer.nil() &&
        parseInt(current.getValue('check_in_odometer'), 10) > parseInt(v.getValue('current_odometer') || '0', 10)) {
        v.setValue('current_odometer', current.getValue('check_in_odometer'));
        v.update();
    }
    FleetVehicleStatus.sync(vehicleId);
    // Finance chargeback (EPIC 11 / D-25) - fired once, on the transition to COMPLETED
    gs.eventQueue('x_1850693_enterp_0.reservation.completed', current, current.getValue('cost_center'), current.getValue('actual_fuel_cost'));
    // Fuel auto-match for this trip (hook; matching rules in FLEET-45)
    FleetFuelMatch.matchReservation(current.getUniqueValue());
})(current, previous);
